55	    const isPlanMode = approvalMode === ApprovalMode.PLAN;
56	    const isYoloMode = approvalMode === ApprovalMode.YOLO;
57	    const skills = context.config.getSkillManager().getSkills();
58	    const toolNames = context.toolRegistry.getAllToolNames();
59	    const enabledToolNames = new Set(toolNames);
60	
61	    const approvedPlanPath = context.config.getApprovedPlanPath();
62	
63	    const desiredModel = resolveModel(
64	      context.config.getActiveModel(),
65	      context.config.getGemini31LaunchedSync?.() ?? false,
66	      context.config.getGemini31FlashLiteLaunchedSync?.() ?? false,
67	      false,
68	      context.config.getHasAccessToPreviewModel?.() ?? true,
69	      context.config,
70	    );
71	    const isModernModel = supportsModernFeatures(desiredModel);
72	    const activeSnippets = isModernModel ? snippets : legacySnippets;
73	    const contextFilenames = getAllGeminiMdFilenames();
74	
75	    let planModeToolsList = '';
76	    if (isPlanMode) {
77	      const allTools = context.toolRegistry.getAllTools();
78	      planModeToolsList = allTools
79	        .map((t) => {
80	          if (t instanceof DiscoveredMCPTool) {
81	            return `  <tool>\`${t.name}\` (${t.serverName})</tool>`;
82	          }
83	          return `  <tool>\`${t.name}\`</tool>`;
84	        })
85	        .join('\n');
86	    }
87	
88	    let basePrompt: string;
89	
90	    // --- Template File Override ---
91	    if (systemMdResolution.value && !systemMdResolution.isDisabled) {
92	      let systemMdPath = path.resolve(path.join(GEMINI_DIR, 'system.md'));
93	      if (!systemMdResolution.isSwitch) {
94	        systemMdPath = systemMdResolution.value;
95	      }
96	      if (!fs.existsSync(systemMdPath)) {
97	        throw new Error(`missing system prompt file '${systemMdPath}'`);
98	      }
99	      basePrompt = fs.readFileSync(systemMdPath, 'utf8');
100	      const skillsPrompt = activeSnippets.renderAgentSkills(
101	        skills.map((s) => ({
102	          name: s.name,
103	          description: s.description,
104	          location: s.location,
105	        })),
106	      );
107	      basePrompt = applySubstitutions(
108	        basePrompt,
109	        context.config,
110	        skillsPrompt,
111	        isModernModel,
112	      );
113	    } else {
114	      // --- Standard Composition ---
115	      const hasHierarchicalMemory =
116	        typeof userMemory === 'object' &&
117	        userMemory !== null &&
118	        (!!userMemory.global?.trim() ||
119	          !!userMemory.extension?.trim() ||
120	          !!userMemory.project?.trim());
121	
122	      const options: snippets.SystemPromptOptions = {
123	        preamble: this.withSection('preamble', () => ({
124	          interactive: interactiveMode,
125	        })),
126	        coreMandates: this.withSection('coreMandates', () => ({
127	          interactive: interactiveMode,
128	          hasSkills: skills.length > 0,
129	          hasHierarchicalMemory,
130	          contextFilenames,
131	          topicUpdateNarration: context.config.isTopicUpdateNarrationEnabled(),
132	        })),
133	        subAgents: this.withSection('agentContexts', () =>
