139	              description: d.description,
140	            })),
141	        ),
142	        agentSkills: this.withSection(
143	          'agentSkills',
144	          () =>
145	            skills.map((s) => ({
146	              name: s.name,
147	              description: s.description,
148	              location: s.location,
149	            })),
150	          skills.length > 0,
151	        ),
152	        taskTracker: context.config.isTrackerEnabled(),
