158	            enableCodebaseInvestigator: enabledToolNames.has(
159	              CodebaseInvestigatorAgent.name,
160	            ),
161	            enableWriteTodosTool: enabledToolNames.has(WRITE_TODOS_TOOL_NAME),
162	            enableEnterPlanModeTool: enabledToolNames.has(
163	              ENTER_PLAN_MODE_TOOL_NAME,
164	            ),
165	            enableGrep: enabledToolNames.has(GREP_TOOL_NAME),
166	            enableGlob: enabledToolNames.has(GLOB_TOOL_NAME),
167	            approvedPlan: approvedPlanPath
